import sys
import re

def evaluate_expression(expr, q):
    # Replace 'q' with the given quantity and evaluate the expression
    expr = expr.replace('q', str(q))
    try:
        return eval(expr)
    except:
        return 0.0

def main():
    template_path = sys.stdin.readline().strip()
    template = open(template_path, 'r').read()

    records = []
    for line in sys.stdin:
        name, quantity_str, expr = line.strip().split(',')
        quantity = float(quantity_str)
        value = evaluate_expression(expr, quantity)
        records.append((name, quantity, value))

    rows = []
    for name, quantity, value in records:
        if value.is_integer():
            value_str = str(int(value))
        else:
            value_str = str(value)
        rows.append(f'<tr><td>{name}</td><td>{value_str}</td></tr>')

    result = template.replace('{{rows}}', '\n'.join(rows))
    print(result)

if __name__ == '__main__':
    main()
